examples:
Standard Page (Single Column):
```tsx
import { PageTemplate } from '@levain/ui-react';

export default function MyPage() {
  return (
    <PageTemplate title="My Page Title" layout="single-column">
      {/* Single-column page content */}
      <p>Your main content here.</p>
    </PageTemplate>
  );
}
```

Two Columns (Sidebar Right Layout):
```tsx
import { PageTemplate } from '@levain/ui-react';

<PageTemplate
  title="Right Sidebar Layout Page"
  layout="two-column-sidebar-right"
  // sidebarColumns={3} // Example: Use 3 columns for sidebar (9 for main)
  sidebar={
    <div style={{ height: 200 }}>Sidebar Content (Default 4 cols)</div>
  }
>
  {/* Main Content (children) */}
  <div style={{ height: 300 }}>Main Content Area (Default 8 cols)</div>
</PageTemplate>
```
